INSERT INTO tasks (id, user_id, goal_id, title, topic, difficulty, url, duration, completed, completed_at, completed_date, created_at, subtopic, is_important, description, notes)
VALUES
  ('dsa-1', 'user-default', 'goal-dsa', 'Two Sum', 'Arrays & Hashing', 'Easy', 'https://leetcode.com/problems/two-sum', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Hash Map Lookup (Complement Tracking)', TRUE, 'Find indices of two numbers that add up to target. Use a hash map to trade O(N) space for O(1) instantaneous complement lookup.', 'Pattern: One-pass Hash Map. For each num, check if (target - num) exists in map. Time: O(N), Space: O(N). Avoid using element at current index twice.'),
  ('dsa-217', 'user-default', 'goal-dsa', 'Contains Duplicate', 'Arrays & Hashing', 'Easy', 'https://leetcode.com/problems/contains-duplicate', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Hash Set / Duplicate Detection', TRUE, 'Determine if any value appears at least twice in an integer array. Hash set tracks uniqueness in linear time.', 'Pattern: Hash Set. Add items one by one; return true immediately on set collision. Time: O(N), Space: O(N). Alternatively sort in O(N log N) for O(1) space.'),
  ('dsa-242', 'user-default', 'goal-dsa', 'Valid Anagram', 'Arrays & Hashing', 'Easy', 'https://leetcode.com/problems/valid-anagram', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Character Frequency Counting', TRUE, 'Determine if two strings are anagrams of each other. Anagrams have identical character frequency distributions.', 'Pattern: Frequency Array [26]. Increment for s, decrement for t. If all counts return to zero, strings are anagrams. Time: O(N), Space: O(1).'),
  ('dsa-383', 'user-default', 'goal-dsa', 'Ransom Note', 'Arrays & Hashing', 'Easy', 'https://leetcode.com/problems/ransom-note', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Frequency Table Matching', TRUE, 'Check if ransom note string can be constructed from magazine letters. Each magazine letter may only be used once.', 'Pattern: Frequency Counting. Count available chars in magazine with array[26]; decrement for ransom note. If any count drops < 0, return false. Time: O(M+N), Space: O(1).'),
  ('dsa-409', 'user-default', 'goal-dsa', 'Longest Palindrome', 'Arrays & Hashing', 'Easy', 'https://leetcode.com/problems/longest-palindrome', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Greedy Even/Odd Frequency Matching', FALSE, 'Find length of longest palindrome that can be built with letters from string by pairing characters.', 'Pattern: Frequency Counting. Count character frequencies. Add all even counts; for odd counts add count - 1; add +1 at end if any odd count exists for center. Time: O(N), Space: O(1).'),
  ('dsa-169', 'user-default', 'goal-dsa', 'Majority Element', 'Arrays & Hashing', 'Easy', 'https://leetcode.com/problems/majority-element', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Boyer-Moore Majority Voting', TRUE, 'Find the element appearing more than ⌊n/2⌋ times. Boyer-Moore eliminates pairing opposites to find candidate in O(1) space.', 'Pattern: Boyer-Moore Voting. Count = 0, candidate = None. If count == 0, candidate = num. Count += 1 if num == candidate else -1. Time: O(N), Space: O(1).'),
  ('dsa-14', 'user-default', 'goal-dsa', 'Longest Common Prefix', 'Arrays & Hashing', 'Easy', 'https://leetcode.com/problems/longest-common-prefix', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Horizontal / Vertical Scanning', FALSE, 'Find the longest common prefix string amongst an array of strings. Compare characters column-by-column across all words.', 'Pattern: Vertical Scanning. Compare character at index i across all strings simultaneously. Stop at first mismatch or word end. Time: O(S), Space: O(1).'),
  ('dsa-49', 'user-default', 'goal-dsa', 'Group Anagrams', 'Arrays & Hashing', 'Medium', 'https://leetcode.com/problems/group-anagrams', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Sorted Key / Frequency Signature Grouping', TRUE, 'Group anagrams together into sublists. Use a canonical representation (sorted string or 26-char count tuple) as hash map key.', 'Pattern: Hash Map with Canonical Key. Key = tuple(char_counts) or ''''.join(sorted(word)). Append word to map[key]. Time: O(N * K log K), Space: O(N * K).'),
  ('dsa-238', 'user-default', 'goal-dsa', 'Product of Array Except Self', 'Arrays & Hashing', 'Medium', 'https://leetcode.com/problems/product-of-array-except-self', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Prefix & Suffix Running Products', TRUE, 'Calculate output array where output[i] equals product of all elements except nums[i] without using division.', 'Pattern: Two-Pass Running Product. Forward pass builds prefix products; backward pass multiplies running suffix product in-place. Time: O(N), Space: O(1) auxiliary.'),
  ('dsa-128', 'user-default', 'goal-dsa', 'Longest Consecutive Sequence', 'Arrays & Hashing', 'Medium', 'https://leetcode.com/problems/longest-consecutive-sequence', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Hash Set Sequence Expansion', TRUE, 'Find length of longest consecutive elements sequence in unsorted array in O(N) time.', 'Pattern: Hash Set Sequence Head. Store all nums in set. Only start counting sequence length if num - 1 is NOT in set (ensures sequence head). Time: O(N), Space: O(N).'),
  ('dsa-271', 'user-default', 'goal-dsa', 'Encode and Decode Strings', 'Arrays & Hashing', 'Medium', 'https://leetcode.com/problems/encode-and-decode-strings', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Length-Prefixed Delimiter Encoding', TRUE, 'Design algorithm to encode list of strings to a string and decode string back to list of strings without delimiter collisions.', 'Pattern: Length-Header Encoding. Format each string as ''{len}#{string}''. Decode by parsing digits up to ''#'' as slice length. Time: O(N), Space: O(1) overhead.'),
  ('dsa-189', 'user-default', 'goal-dsa', 'Rotate Array', 'Arrays & Hashing', 'Medium', 'https://leetcode.com/problems/rotate-array', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Array Reverse Slicing', FALSE, 'Rotate array to right by k steps in-place. k = k % n prevents redundant cycles.', 'Pattern: Three-Reversal Trick. Reverse entire array, reverse first k elements, reverse remaining n - k elements. Time: O(N), Space: O(1).'),
  ('dsa-179', 'user-default', 'goal-dsa', 'Largest Number', 'Arrays & Hashing', 'Medium', 'https://leetcode.com/problems/largest-number', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Custom Concatenation Comparator ((a+b) vs (b+a))', FALSE, 'Given list of non-negative integers, arrange them such that they form largest number.', 'Pattern: Custom Sorting Comparator. Compare two numbers a and b as strings: if a + b > b + a, a should come before b. Sort using custom comparator. Strip leading zeroes for [0, 0]. Time: O(N log N * K), Space: O(N).'),
  ('dsa-8', 'user-default', 'goal-dsa', 'String to Integer (atoi)', 'Arrays & Hashing', 'Medium', 'https://leetcode.com/problems/string-to-integer-atoi', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Finite State Machine / Strict Clamp String Parser', FALSE, 'Implement myAtoi(string s) which converts string to 32-bit signed integer with whitespace trimming, sign check, and integer clamping.', 'Pattern: Deterministic Parsing State. 1) Discard leading whitespace. 2) Check for optional ''+'' or ''-'' sign. 3) Read consecutive digits, clamping to [-2^31, 2^31 - 1] on overflow. Time: O(N), Space: O(1).'),
  ('dsa-380', 'user-default', 'goal-dsa', 'Insert Delete GetRandom O(1)', 'Arrays & Hashing', 'Medium', 'https://leetcode.com/problems/insert-delete-getrandom-o1', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Dynamic Array + Hash Index Swap-and-Pop', TRUE, 'Design data structure supporting insert, remove, and getRandom in average O(1) time.', 'Pattern: Hash Map + Dynamic Array. Map stores val -> array index. To delete O(1), swap target with last element in array, update map, pop back. Time: O(1), Space: O(N).'),
  ('dsa-41', 'user-default', 'goal-dsa', 'First Missing Positive', 'Arrays & Hashing', 'Hard', 'https://leetcode.com/problems/first-missing-positive', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'In-Place Value-Index Cyclic Placement', TRUE, 'Find smallest missing positive integer in unsorted array in O(N) time and O(1) auxiliary space.', 'Pattern: Cyclic Sort / Index As Hash Key. Place each positive x in range [1, n] at nums[x - 1] via while-swaps. First index i where nums[i] != i + 1 yields i + 1. Time: O(N), Space: O(1).'),
  ('dsa-125', 'user-default', 'goal-dsa', 'Valid Palindrome', 'Two Pointers', 'Easy', 'https://leetcode.com/problems/valid-palindrome', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Inward Pointers / Alpha-Numeric Filter', TRUE, 'Determine if string is palindrome considering only alphanumeric characters and ignoring cases.', 'Pattern: Inward Two Pointers. Left at 0, right at n - 1. Increment left/decrement right over non-alphanumeric chars; compare lowercase chars. Time: O(N), Space: O(1).'),
  ('dsa-283', 'user-default', 'goal-dsa', 'Move Zeroes', 'Two Pointers', 'Easy', 'https://leetcode.com/problems/move-zeroes', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Fast & Slow In-Place Partition', TRUE, 'Move all 0''s to end of array while maintaining relative order of non-zero elements in-place.', 'Pattern: Read/Write Pointers. Slow pointer tracks position for next non-zero. Fast pointer scans array and swaps non-zeroes forward. Time: O(N), Space: O(1).'),
  ('dsa-1019', 'user-default', 'goal-dsa', 'Squares of a Sorted Array', 'Two Pointers', 'Easy', 'https://leetcode.com/problems/squares-of-a-sorted-array', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Two Pointers on Symmetrically Sorted Array', TRUE, 'Given sorted integer array (containing negative numbers), return array of squares in sorted order.', 'Pattern: Inward Pointers from Extremes. Largest squares occur at either extreme left (large negatives) or extreme right (large positives). Fill result backwards. Time: O(N), Space: O(1).'),
  ('dsa-11', 'user-default', 'goal-dsa', 'Container With Most Water', 'Two Pointers', 'Medium', 'https://leetcode.com/problems/container-with-most-water', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Shrinking Inward Window / Greedy Height', TRUE, 'Find two lines that together with x-axis forms container holding maximum water.', 'Pattern: Greedy Inward Pointers. Left = 0, right = n - 1. Area = (right - left) * min(h[left], h[right]). Greedily move the pointer with smaller height inward. Time: O(N), Space: O(1).'),
  ('dsa-15', 'user-default', 'goal-dsa', '3Sum', 'Two Pointers', 'Medium', 'https://leetcode.com/problems/3sum', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Sorted Base Element + Two Pointers', TRUE, 'Find all unique triplets in array that sum to zero.', 'Pattern: Sort + Two Pointers. Sort array. Fix nums[i]; use left/right pointers to find pairs summing to -nums[i]. Skip duplicate values for i, left, and right. Time: O(N^2), Space: O(1) or O(N) sort.'),
  ('dsa-16', 'user-default', 'goal-dsa', '3Sum Closest', 'Two Pointers', 'Medium', 'https://leetcode.com/problems/3sum-closest', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Sorted Search / Closest Distance Tracking', FALSE, 'Find three integers in array whose sum is closest to target.', 'Pattern: Sort + Two Pointers. Sort array. For each base element, use two pointers inward; update closest_sum if |sum - target| < |closest - target|. Time: O(N^2), Space: O(1).'),
  ('dsa-75', 'user-default', 'goal-dsa', 'Sort Colors', 'Two Pointers', 'Medium', 'https://leetcode.com/problems/sort-colors', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Dutch National Flag 3-Way Partitioning', TRUE, 'Sort array with values 0, 1, 2 in-place in a single pass without using library sort.', 'Pattern: Dijkstra''s 3-Way Partition. Pointers low, mid, high. Swap 0s to low, 2s to high, increment mid on 1. All elements partitioned in one pass. Time: O(N), Space: O(1).'),
  ('dsa-31', 'user-default', 'goal-dsa', 'Next Permutation', 'Two Pointers', 'Medium', 'https://leetcode.com/problems/next-permutation', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Lexicographical Suffix Pivot & Inversion', TRUE, 'Rearrange numbers into lexicographically next greater permutation in-place.', 'Pattern: Next Permutation Algorithm. 1) Find largest i where nums[i] < nums[i+1]. 2) Find largest j > i where nums[j] > nums[i]. 3) Swap nums[i] and nums[j]. 4) Reverse suffix nums[i+1:]. Time: O(N), Space: O(1).'),
  ('dsa-5', 'user-default', 'goal-dsa', 'Longest Palindromic Substring', 'Two Pointers', 'Medium', 'https://leetcode.com/problems/longest-palindromic-substring', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Expand Around Centers (2N - 1 Centers)', TRUE, 'Find longest palindromic substring in s in O(N^2) time and O(1) space.', 'Pattern: Two Pointers Center Expansion. There are 2N - 1 possible centers: single characters (i) for odd palindromes and pairs (i, i+1) for even palindromes. Expand outward while characters match. Time: O(N^2), Space: O(1).'),
  ('dsa-121', 'user-default', 'goal-dsa', 'Best Time to Buy and Sell Stock', 'Sliding Window', 'Easy', 'https://leetcode.com/problems/best-time-to-buy-and-sell-stock', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Running Minimum & Profit Tracking', TRUE, 'Find maximum profit by choosing a single day to buy stock and a different day in future to sell.', 'Pattern: One-Pass Min-Tracking Window. Track min_price seen so far; at each price, potential profit is price - min_price. Time: O(N), Space: O(1).'),
  ('dsa-3', 'user-default', 'goal-dsa', 'Longest Substring Without Repeating Characters', 'Sliding Window', 'Medium', 'https://leetcode.com/problems/longest-substring-without-repeating-characters', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Dynamic Window with Last Seen Index', TRUE, 'Find length of longest substring without repeating characters.', 'Pattern: Variable-Size Sliding Window. Expand right pointer. Store last seen index of each char in hash map. If char seen within window, slide left to map[char] + 1. Time: O(N), Space: O(min(N, M)).'),
  ('dsa-438', 'user-default', 'goal-dsa', 'Find All Anagrams in a String', 'Sliding Window', 'Medium', 'https://leetcode.com/problems/find-all-anagrams-in-a-string', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Fixed-Size Frequency Window Matching', TRUE, 'Find all start indices of p''s anagrams in s.', 'Pattern: Fixed Window of size len(p). Maintain character frequency array for window in s. Slide window one step: add right char count, remove left char count. Compare arrays in O(1). Time: O(N), Space: O(1).'),
  ('dsa-424', 'user-default', 'goal-dsa', 'Longest Repeating Character Replacement', 'Sliding Window', 'Medium', 'https://leetcode.com/problems/longest-repeating-character-replacement', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Dynamic Window with Max Frequency Count', TRUE, 'Find length of longest substring containing same letter after replacing at most k characters.', 'Pattern: Sliding Window with Max Frequency. Window validity condition: window_len - max_freq <= k. If invalid, increment left pointer. Window never needs to shrink in max size. Time: O(N), Space: O(1).'),
  ('dsa-76', 'user-default', 'goal-dsa', 'Minimum Window Substring', 'Sliding Window', 'Hard', 'https://leetcode.com/problems/minimum-window-substring', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Variable Window with Frequency Validation', TRUE, 'Find minimum window substring in s that contains all characters of t in O(N) time.', 'Pattern: Minimum Sliding Window. Expand right to satisfy frequency requirements (have == need). Contract left pointer while window remains valid to find local minimum. Time: O(N), Space: O(total chars).'),
  ('dsa-239', 'user-default', 'goal-dsa', 'Sliding Window Maximum', 'Sliding Window', 'Hard', 'https://leetcode.com/problems/sliding-window-maximum', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Monotonic Decreasing Deque Window', TRUE, 'Return maximum sliding window of size k moving across array from left to right in O(N) time.', 'Pattern: Monotonic Deque. Store array indices in deque with values in strictly decreasing order. Pop front indices older than left boundary; pop back indices whose values are <= incoming element. Time: O(N), Space: O(k).'),
  ('dsa-560', 'user-default', 'goal-dsa', 'Subarray Sum Equals K', 'Prefix Sum & Subarrays', 'Medium', 'https://leetcode.com/problems/subarray-sum-equals-k', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Cumulative Sum Hash Map (Sum - K)', TRUE, 'Find total number of contiguous subarrays whose sum equals k in O(N) time.', 'Pattern: Prefix Sum + Hash Map. Subarray sum(i, j) = prefix[j] - prefix[i-1] == k => prefix[i-1] == prefix[j] - k. Maintain frequency map of prefix sums; add count of (curr_sum - k) at each step. Time: O(N), Space: O(N).'),
  ('dsa-525', 'user-default', 'goal-dsa', 'Contiguous Array', 'Prefix Sum & Subarrays', 'Medium', 'https://leetcode.com/problems/contiguous-array', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Prefix Sum Relative Offset Hash Map', TRUE, 'Find maximum length of contiguous subarray with equal number of 0s and 1s.', 'Pattern: Transformed Prefix Sum. Treat 0 as -1 and 1 as +1. Equal 0s and 1s means running sum returns to a previously seen value. Store first occurrence index of each prefix sum in map. Time: O(N), Space: O(N).'),
  ('dsa-912', 'user-default', 'goal-dsa', 'Random Pick with Weight', 'Prefix Sum & Subarrays', 'Medium', 'https://leetcode.com/problems/random-pick-with-weight', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Prefix Sum Array + Binary Search Probability Pick', FALSE, 'Given array of positive integers w, randomly pick an index in proportion to its weight w[i].', 'Pattern: Prefix Sums + Binary Search. Compute prefix sum of weights array where total = prefix[-1]. Generate random target in [0, total). Use binary search (bisect_right) to find index in O(log N) per pick. Time: O(log N), Space: O(N).'),
  ('dsa-252', 'user-default', 'goal-dsa', 'Meeting Rooms', 'Intervals', 'Easy', 'https://leetcode.com/problems/meeting-rooms', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Start Time Sorting / Overlap Detection', TRUE, 'Determine if a person could attend all meetings given array of meeting time intervals.', 'Pattern: Interval Sorting. Sort meetings by start time: intervals.sort(key=lambda x: x[0]). Attendable iff intervals[i][0] >= intervals[i-1][1] for all consecutive meetings. Time: O(N log N), Space: O(1).'),
  ('dsa-56', 'user-default', 'goal-dsa', 'Merge Intervals', 'Intervals', 'Medium', 'https://leetcode.com/problems/merge-intervals', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Sorting Intervals / Running End Extension', TRUE, 'Merge all overlapping intervals and return array of non-overlapping intervals.', 'Pattern: Sort + Merge. Sort by interval start. If current start <= previous end, merge by end = max(previous.end, current.end); else append new interval. Time: O(N log N), Space: O(N).'),
  ('dsa-57', 'user-default', 'goal-dsa', 'Insert Interval', 'Intervals', 'Medium', 'https://leetcode.com/problems/insert-interval', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Linear Partition / Merge Overlapping', TRUE, 'Insert new interval into sorted non-overlapping intervals and merge if necessary.', 'Pattern: 3-Stage Linear Pass. 1) Append intervals ending before newInterval starts. 2) Merge all overlapping intervals into newInterval (min start, max end). 3) Append remaining intervals. Time: O(N), Space: O(N).'),
  ('dsa-253', 'user-default', 'goal-dsa', 'Meeting Rooms II', 'Intervals', 'Medium', 'https://leetcode.com/problems/meeting-rooms-ii', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Min-Heap End Times / Sweep-Line', TRUE, 'Find minimum number of conference rooms required to hold all meetings.', 'Pattern: Min-Heap or Sweep Line. Sort meetings by start time. Push end times into min-heap. If earliest ending meeting ends before current start, pop heap (reuse room); push current end time. Heap size is rooms needed. Time: O(N log N), Space: O(N).'),
  ('dsa-435', 'user-default', 'goal-dsa', 'Non-overlapping Intervals', 'Intervals', 'Medium', 'https://leetcode.com/problems/non-overlapping-intervals', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Greedy Earliest Finish Time Selection', TRUE, 'Find minimum number of intervals to remove to make the rest of intervals non-overlapping.', 'Pattern: Greedy Activity Selection. Sort intervals by end time. Always keep interval that finishes earliest. If next interval starts before current end, increment removal count; otherwise update current end. Time: O(N log N), Space: O(1).'),
  ('dsa-761', 'user-default', 'goal-dsa', 'Employee Free Time', 'Intervals', 'Hard', 'https://leetcode.com/problems/employee-free-time', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Interval Flattening & Free Gap Extraction', TRUE, 'Find list of common free time intervals for all employees given their working schedules.', 'Pattern: Interval Merging Sweep. Flatten all employee work intervals into one list and sort by start time. Merge overlapping working intervals; gaps between consecutive merged work blocks constitute common free time. Time: O(N log N), Space: O(N).'),
  ('dsa-20', 'user-default', 'goal-dsa', 'Valid Parentheses', 'Stack & Queue', 'Easy', 'https://leetcode.com/problems/valid-parentheses', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Matching Bracket LIFO Stack', TRUE, 'Determine if input string containing brackets ''()[]{}'' is valid and properly closed in correct order.', 'Pattern: LIFO Stack. Push opening brackets (or expected closing brackets) to stack. On closing bracket, pop and verify matching type. Stack must be empty at end. Time: O(N), Space: O(N).'),
  ('dsa-874', 'user-default', 'goal-dsa', 'Backspace String Compare', 'Stack & Queue', 'Easy', 'https://leetcode.com/problems/backspace-string-compare', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Keystroke Simulation Stack', FALSE, 'Compare two strings containing ''#'' backspaces to verify if they produce equal keystroke text.', 'Pattern: Stack Simulation. Push characters to stack; pop on ''#'' if stack non-empty. Compare resulting stack contents. Can also be optimized with backwards two pointers. Time: O(M+N), Space: O(M+N).'),
  ('dsa-232', 'user-default', 'goal-dsa', 'Implement Queue using Stacks', 'Stack & Queue', 'Easy', 'https://leetcode.com/problems/implement-queue-using-stacks', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Amortized Two-Stack Queue Implementation', TRUE, 'Implement first-in-first-out (FIFO) queue using only two LIFO stacks.', 'Pattern: In-Stack & Out-Stack. Push directly to in_stack. For pop/peek, if out_stack is empty, pop all elements from in_stack and push to out_stack (reverses order to FIFO). Amortized Time: O(1), Space: O(N).'),
  ('dsa-155', 'user-default', 'goal-dsa', 'Min Stack', 'Stack & Queue', 'Medium', 'https://leetcode.com/problems/min-stack', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Paired State / Auxiliary Min Stack', TRUE, 'Design stack that supports push, pop, top, and retrieving minimum element in O(1) time.', 'Pattern: Dual Stack or Tuple Pairs. Push (val, min(val, min_so_far)) onto single stack, or maintain parallel min_stack where top is always current minimum. Time: O(1) all ops, Space: O(N).'),
  ('dsa-150', 'user-default', 'goal-dsa', 'Evaluate Reverse Polish Notation', 'Stack & Queue', 'Medium', 'https://leetcode.com/problems/evaluate-reverse-polish-notation', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Operand Stack Postfix Evaluation', TRUE, 'Evaluate value of arithmetic expression in Reverse Polish Notation (RPN).', 'Pattern: Postfix Evaluation Stack. Numbers are pushed onto stack. On operator (+, -, *, /), pop right operand then left operand, perform operation, push result back. Division truncates toward zero. Time: O(N), Space: O(N).'),
  ('dsa-739', 'user-default', 'goal-dsa', 'Daily Temperatures', 'Stack & Queue', 'Medium', 'https://leetcode.com/problems/daily-temperatures', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Monotonic Decreasing Stack for Next Greater', TRUE, 'Given daily temperatures, return array where answer[i] is number of days to wait for warmer temperature.', 'Pattern: Monotonic Decreasing Stack. Store temperature indices. When current temperature is warmer than stack top, pop index and set answer[popped] = current_i - popped. Time: O(N), Space: O(N).'),
  ('dsa-735', 'user-default', 'goal-dsa', 'Asteroid Collision', 'Stack & Queue', 'Medium', 'https://leetcode.com/problems/asteroid-collision', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Collision Simulation Stack', TRUE, 'Find state of asteroids after all collisions: positive moves right, negative moves left; larger destroys smaller.', 'Pattern: Collision Stack. Push asteroids. Collision only occurs if top is positive (> 0) and current is negative (< 0). Loop pop while top is smaller; destroy both if equal; push current only if it survives. Time: O(N), Space: O(N).'),
  ('dsa-394', 'user-default', 'goal-dsa', 'Decode String', 'Stack & Queue', 'Medium', 'https://leetcode.com/problems/decode-string', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Multiplier and String Accumulator Stack', TRUE, 'Decode encoded string where k[encoded_string] repeats encoded_string exactly k times.', 'Pattern: Nested Expression Stack. Track curr_str and curr_num. On ''['', push (curr_str, curr_num) onto stack, reset curr_str = '''', curr_num = 0. On '']'', pop (prev_str, repeat_num) and curr_str = prev_str + curr_str * repeat_num. Time: O(Output Length), Space: O(N).'),
  ('dsa-227', 'user-default', 'goal-dsa', 'Basic Calculator II', 'Stack & Queue', 'Medium', 'https://leetcode.com/problems/basic-calculator-ii', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Operator Precedence Evaluation Stack', TRUE, 'Implement basic calculator to evaluate string containing non-negative integers and operators ''+'', ''-'', ''*'', ''/''.', 'Pattern: Precedence Stack. Process numbers with previous operator. For ''+'' push num, for ''-'' push -num, for ''*'' and ''/'' pop top and evaluate immediately. Sum all numbers on stack at end. Time: O(N), Space: O(N).'),
  ('dsa-362', 'user-default', 'goal-dsa', 'Design Hit Counter', 'Stack & Queue', 'Medium', 'https://leetcode.com/problems/design-hit-counter', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Sliding Second Deque / Queue Rolling Count', FALSE, 'Design hit counter which counts number of hits received in past 5 minutes (300 seconds).', 'Pattern: Time Window Deque or Ring Buffer. Store hits as (timestamp, count) in deque. For getHits(t), pop front timestamps <= t - 300. Return sum of surviving counts in deque. Time: O(1) amortized, Space: O(300).'),
  ('dsa-42', 'user-default', 'goal-dsa', 'Trapping Rain Water', 'Stack & Queue', 'Hard', 'https://leetcode.com/problems/trapping-rain-water', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Monotonic Stack / Two Pointers Water Trap', TRUE, 'Compute how much water elevation map can trap after raining.', 'Pattern: Inward Two Pointers with Max Tracking. Water above bar i is min(left_max, right_max) - height[i]. Advance the pointer with smaller max boundary inward accumulating trapped water. Time: O(N), Space: O(1).'),
  ('dsa-84', 'user-default', 'goal-dsa', 'Largest Rectangle in Histogram', 'Stack & Queue', 'Hard', 'https://leetcode.com/problems/largest-rectangle-in-histogram', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Monotonic Increasing Stack Histogram Area', TRUE, 'Find area of largest rectangle in histogram bars in O(N) time.', 'Pattern: Monotonic Increasing Stack of Indices. When current bar is shorter than stack top, pop bar h; it forms rectangle of height h between current index and new stack top. Append sentinel 0 height at end to flush stack. Time: O(N), Space: O(N).'),
  ('dsa-32', 'user-default', 'goal-dsa', 'Longest Valid Parentheses', 'Stack & Queue', 'Hard', 'https://leetcode.com/problems/longest-valid-parentheses', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Index Stack / Balance Tracking Parentheses', TRUE, 'Find length of longest valid (well-formed) parentheses substring.', 'Pattern: Index Stack. Initialize stack with -1 as base index. Push index of ''(''. On '')'', pop stack. If stack empty, push current index as new base; else max_len = max(max_len, i - stack_top). Time: O(N), Space: O(N).'),
  ('dsa-931', 'user-default', 'goal-dsa', 'Maximum Frequency Stack', 'Stack & Queue', 'Hard', 'https://leetcode.com/problems/maximum-frequency-stack', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Frequency Map to Stacks (FreqStack)', FALSE, 'Design stack-like data structure that pops most frequent element; if tie, pops element closest to top.', 'Pattern: Frequency-to-Stack Map. Map val -> freq, and map freq -> stack of elements. Track max_freq. Push increments freq and pushes to group[freq]. Pop pops from group[max_freq] and decrements max_freq if empty. Time: O(1) all ops, Space: O(N).'),
  ('dsa-224', 'user-default', 'goal-dsa', 'Basic Calculator', 'Stack & Queue', 'Hard', 'https://leetcode.com/problems/basic-calculator', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Unary Sign & Subexpression Parentheses Stack', TRUE, 'Implement basic calculator to evaluate string containing integers, ''+'', ''-'', ''('', and '')''.', 'Pattern: Sign & Parentheses Stack. Track result and current sign (+1 or -1). On ''('', push (result, sign) to stack and reset. On '')'', pop (prev_result, prev_sign) and compute prev_result + prev_sign * result. Time: O(N), Space: O(N).'),
  ('dsa-206', 'user-default', 'goal-dsa', 'Reverse Linked List', 'Linked List', 'Easy', 'https://leetcode.com/problems/reverse-linked-list', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Iterative 3-Pointer Node Inversion', TRUE, 'Reverse a singly linked list in-place and return new head.', 'Pattern: In-Place Pointer Reversal. Maintain prev = None, curr = head. Save nxt = curr.next, point curr.next = prev, advance prev = curr, curr = nxt. Return prev. Time: O(N), Space: O(1).'),
  ('dsa-21', 'user-default', 'goal-dsa', 'Merge Two Sorted Lists', 'Linked List', 'Easy', 'https://leetcode.com/problems/merge-two-sorted-lists', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Dummy Sentinel Two-Pointer Merge', TRUE, 'Merge two sorted linked lists into one sorted list by splicing nodes together.', 'Pattern: Dummy Sentinel Head. Use dummy node. Compare l1.val and l2.val; attach smaller node to tail; advance corresponding pointer. Attach non-null remainder list at end. Time: O(N+M), Space: O(1).'),
  ('dsa-141', 'user-default', 'goal-dsa', 'Linked List Cycle', 'Linked List', 'Easy', 'https://leetcode.com/problems/linked-list-cycle', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Floyd''s Fast & Slow Cycle Detection', TRUE, 'Determine if linked list has a cycle using O(1) memory.', 'Pattern: Floyd''s Tortoise and Hare. Slow moves 1 step, fast moves 2 steps. If fast or fast.next reaches null, no cycle; if slow and fast meet, cycle detected. Time: O(N), Space: O(1).'),
  ('dsa-908', 'user-default', 'goal-dsa', 'Middle of the Linked List', 'Linked List', 'Easy', 'https://leetcode.com/problems/middle-of-the-linked-list', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Fast & Slow Midpoint Traversal', TRUE, 'Return middle node of linked list; if two middle nodes, return the second middle node.', 'Pattern: 2-to-1 Speed Pointers. Slow moves 1 step, fast moves 2 steps. When fast reaches end of list (fast is null or fast.next is null), slow is exactly at middle node. Time: O(N), Space: O(1).'),
  ('dsa-234', 'user-default', 'goal-dsa', 'Palindrome Linked List', 'Linked List', 'Easy', 'https://leetcode.com/problems/palindrome-linked-list', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Midpoint Split + Half Reversal + Two Pointers', TRUE, 'Determine if singly linked list is palindrome in O(N) time and O(1) space.', 'Pattern: Split, Reverse & Compare. 1) Find middle with slow/fast. 2) Reverse second half in-place. 3) Compare nodes from head and reversed second half. Restore list optionally. Time: O(N), Space: O(1).'),
  ('dsa-19', 'user-default', 'goal-dsa', 'Remove Nth Node From End of List', 'Linked List', 'Medium', 'https://leetcode.com/problems/remove-nth-node-from-end-of-list', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Offset Pointer Window Deletion', TRUE, 'Remove nth node from end of list and return head in one pass.', 'Pattern: Offset Fast/Slow Pointers. Use dummy node before head. Advance fast pointer n + 1 steps ahead. Move both fast and slow together until fast is null; slow.next = slow.next.next. Time: O(N), Space: O(1).'),
  ('dsa-24', 'user-default', 'goal-dsa', 'Swap Nodes in Pairs', 'Linked List', 'Medium', 'https://leetcode.com/problems/swap-nodes-in-pairs', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Iterative Pair Pointer Swapping', FALSE, 'Swap every two adjacent nodes in singly linked list without modifying node values.', 'Pattern: Dummy Head + 3-Pointer Rewire. Dummy points to head. For pair (first, second), point dummy.next = second, first.next = second.next, second.next = first; advance dummy. Time: O(N), Space: O(1).'),
  ('dsa-2', 'user-default', 'goal-dsa', 'Add Two Numbers', 'Linked List', 'Medium', 'https://leetcode.com/problems/add-two-numbers', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Carry Forward Node-by-Node Addition', TRUE, 'Add two numbers represented by linked lists in reverse order; return sum as linked list.', 'Pattern: Full Adder Simulation with Carry. Traverse both lists together. Node val = (v1 + v2 + carry) % 10, carry = (v1 + v2 + carry) // 10. Append extra node for final carry if > 0. Time: O(max(N, M)), Space: O(max(N, M)).'),
  ('dsa-328', 'user-default', 'goal-dsa', 'Odd Even Linked List', 'Linked List', 'Medium', 'https://leetcode.com/problems/odd-even-linked-list', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Odd & Even Pointer Partitioning', FALSE, 'Group all odd nodes together followed by even nodes in-place in O(N) time and O(1) extra space.', 'Pattern: Two Pointers Chain Partitioning. Maintain odd and even pointers and save even_head. Connect odd.next = even.next; advance odd; connect even.next = odd.next; advance even. Join odd.next = even_head. Time: O(N), Space: O(1).'),
  ('dsa-61', 'user-default', 'goal-dsa', 'Rotate List', 'Linked List', 'Medium', 'https://leetcode.com/problems/rotate-list', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Circular Ring Break Rotation', FALSE, 'Rotate list to right by k places in-place.', 'Pattern: Circular Ring Splitting. Find list length and connect tail to head, forming circular list. New tail is at index (length - k % length - 1); break circular link after new tail. Time: O(N), Space: O(1).'),
  ('dsa-143', 'user-default', 'goal-dsa', 'Reorder List', 'Linked List', 'Medium', 'https://leetcode.com/problems/reorder-list', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Find Midpoint + Reverse Half + Alternating Merge', TRUE, 'Reorder linked list L0 -> L1 -> ... -> Ln-1 -> Ln into L0 -> Ln -> L1 -> Ln-1 -> L2 -> Ln-2 in-place.', 'Pattern: 3-Step In-Place Reorder. 1) Find middle with slow/fast. 2) Reverse second half. 3) Weave nodes alternately between first half and reversed second half. Time: O(N), Space: O(1).'),
  ('dsa-287', 'user-default', 'goal-dsa', 'Find the Duplicate Number', 'Linked List', 'Medium', 'https://leetcode.com/problems/find-the-duplicate-number', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Floyd''s Tortoise and Hare on Array Pointers', TRUE, 'Find duplicate number in array of n + 1 integers where each integer is in [1, n] in O(N) time and O(1) space.', 'Pattern: Array as Implicit Linked List Cycle. Treat nums[i] as pointer to next index nums[nums[i]]. Apply Floyd''s fast/slow pointers to find cycle intersection, then reset slow to 0 to locate entrance. Time: O(N), Space: O(1).'),
  ('dsa-148', 'user-default', 'goal-dsa', 'Sort List', 'Linked List', 'Medium', 'https://leetcode.com/problems/sort-list', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Top-Down / Bottom-Up Merge Sort on Lists', FALSE, 'Sort linked list in O(N log N) time and O(log N) or O(1) space.', 'Pattern: Merge Sort on Linked List. Find middle using slow/fast and split into two lists. Recursively sort each half; merge two sorted lists using dummy head helper. Time: O(N log N), Space: O(log N) call stack.'),
  ('dsa-146', 'user-default', 'goal-dsa', 'LRU Cache', 'Linked List', 'Medium', 'https://leetcode.com/problems/lru-cache', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Doubly Linked List + Hash Map Node Index', TRUE, 'Design Least Recently Used (LRU) cache supporting get and put in O(1) time.', 'Pattern: Hash Map + Doubly Linked List. Map stores key -> Node. DLL maintains usage order (most recent at head, least recent at tail) with dummy head and tail. On get/put, move node to head; on capacity, evict node at tail. Time: O(1) all ops, Space: O(capacity).'),
  ('dsa-25', 'user-default', 'goal-dsa', 'Reverse Nodes in k-Group', 'Linked List', 'Hard', 'https://leetcode.com/problems/reverse-nodes-in-k-group', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'K-Group Iterative Sublist Inversion', TRUE, 'Reverse nodes of linked list k at a time; leave remaining nodes as-is if fewer than k remain.', 'Pattern: K-Node Lookahead & Segment Reversal. Count k nodes ahead. If k nodes exist, reverse k nodes segment in-place, connect with previous segment tail and recurse/iterate on next segment. Time: O(N), Space: O(1) iterative.'),
  ('dsa-792', 'user-default', 'goal-dsa', 'Binary Search', 'Binary Search', 'Easy', 'https://leetcode.com/problems/binary-search', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Classic Left/Right Midpoint Convergence', TRUE, 'Search target in sorted array in O(log N) time.', 'Pattern: Classic Binary Search. low = 0, high = n - 1. mid = low + (high - low) // 2. If nums[mid] == target return mid; else narrow search half. Time: O(log N), Space: O(1).'),
  ('dsa-278', 'user-default', 'goal-dsa', 'First Bad Version', 'Binary Search', 'Easy', 'https://leetcode.com/problems/first-bad-version', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Leftmost True Predicate Boundary Search', TRUE, 'Find first bad version using API isBadVersion(v) while minimizing calls.', 'Pattern: Monotonic Predicate Binary Search. low = 1, high = n. If isBadVersion(mid) is true, first bad version could be mid or to the left (high = mid); else low = mid + 1. Returns low. Time: O(log N), Space: O(1).'),
  ('dsa-33', 'user-default', 'goal-dsa', 'Search in Rotated Sorted Array', 'Binary Search', 'Medium', 'https://leetcode.com/problems/search-in-rotated-sorted-array', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Sorted Half Determination & Pivot Branching', TRUE, 'Search target in rotated sorted array with distinct values in O(log N) time.', 'Pattern: Rotated Binary Search. At mid, at least one half [low, mid] or [mid, high] is normally sorted. Check if target lies within bounds of the sorted half; if yes search it, else search opposite half. Time: O(log N), Space: O(1).'),
  ('dsa-153', 'user-default', 'goal-dsa', 'Find Minimum in Rotated Sorted Array', 'Binary Search', 'Medium', 'https://leetcode.com/problems/find-minimum-in-rotated-sorted-array', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Rotated Invariant Inflection Point Search', TRUE, 'Find minimum element in rotated sorted array of unique elements in O(log N) time.', 'Pattern: Inflection Point Search. Compare nums[mid] with nums[high]. If nums[mid] > nums[high], minimum lies strictly to the right (low = mid + 1); else minimum is at mid or left (high = mid). Time: O(log N), Space: O(1).'),
  ('dsa-74', 'user-default', 'goal-dsa', 'Search a 2D Matrix', 'Binary Search', 'Medium', 'https://leetcode.com/problems/search-a-2d-matrix', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Virtual 1D to 2D Row/Col Coordinate Mapping', TRUE, 'Search target in m x n integer matrix where each row is sorted and first integer of each row is greater than last of previous.', 'Pattern: Virtual 1D Array. Matrix maps to 1D index 0 .. m*n - 1. For mid, matrix[mid // n][mid % n] gives cell value. Standard binary search runs in O(log(M*N)) time. Space: O(1).'),
  ('dsa-1023', 'user-default', 'goal-dsa', 'Time Based Key-Value Store', 'Binary Search', 'Medium', 'https://leetcode.com/problems/time-based-key-value-store', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Bucket Array + Upper Bound Timestamp Search', TRUE, 'Design time-based key-value store that stores multiple values at different timestamps and retrieves key''s value at timestamp_prev <= timestamp.', 'Pattern: Hash Map to Sorted List + Binary Search. Map key -> list of (timestamp, value). Since timestamps are strictly increasing, use binary search (bisect_right - 1) to find largest timestamp <= query. Time: O(log N) get, O(1) set, Space: O(N).'),
  ('dsa-658', 'user-default', 'goal-dsa', 'Find K Closest Elements', 'Binary Search', 'Medium', 'https://leetcode.com/problems/find-k-closest-elements', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Binary Search on Left Bound Window', FALSE, 'Find k closest elements to x in sorted array; return sorted result.', 'Pattern: Binary Search on Window Start. Search for optimal start index in range [0, n - k]. Compare distance: if x - arr[mid] > arr[mid + k] - x, window must shift right (low = mid + 1); else high = mid. Time: O(log(N - k) + k), Space: O(k).'),
  ('dsa-4', 'user-default', 'goal-dsa', 'Median of Two Sorted Arrays', 'Binary Search', 'Hard', 'https://leetcode.com/problems/median-of-two-sorted-arrays', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Dual Array Median Partition Balancing', TRUE, 'Find median of two sorted arrays of sizes m and n in O(log(min(m, n))) time.', 'Pattern: Partition Balancing Binary Search. Binary search partition cut in smaller array. Derive partition cut in second array such that left partition has half total elements and max(left1, left2) <= min(right1, right2). Time: O(log(min(M, N))), Space: O(1).'),
  ('dsa-73', 'user-default', 'goal-dsa', 'Set Matrix Zeroes', 'Matrix', 'Medium', 'https://leetcode.com/problems/set-matrix-zeroes', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'In-Place First Row & Column Sentinel Flags', TRUE, 'Given m x n matrix, if element is 0, set entire row and column to 0 in-place in O(1) space.', 'Pattern: First Row & Column as Flags. Use row 0 and col 0 to store zeroes flags for matrix body. Use separate boolean variables to track whether row 0 and col 0 originally contained zeroes. Time: O(M*N), Space: O(1).'),
  ('dsa-48', 'user-default', 'goal-dsa', 'Rotate Image', 'Matrix', 'Medium', 'https://leetcode.com/problems/rotate-image', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Transpose Matrix then Reverse Rows', TRUE, 'Rotate n x n 2D matrix by 90 degrees clockwise in-place.', 'Pattern: Transpose + Horizontal Reflection. 1) Transpose matrix (swap matrix[i][j] with matrix[j][i] across main diagonal). 2) Reverse each row horizontally: row.reverse(). Time: O(N^2), Space: O(1).'),
  ('dsa-54', 'user-default', 'goal-dsa', 'Spiral Matrix', 'Matrix', 'Medium', 'https://leetcode.com/problems/spiral-matrix', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Four Boundary Contraction Traversal', TRUE, 'Return all elements of m x n matrix in spiral order.', 'Pattern: 4-Boundary Pointers (top, bottom, left, right). Traverse top row left-to-right, contract top; traverse right column top-to-bottom, contract right; traverse bottom row right-to-left, contract bottom; traverse left column bottom-to-top, contract left. Time: O(M*N), Space: O(1) auxiliary.'),
  ('dsa-36', 'user-default', 'goal-dsa', 'Valid Sudoku', 'Matrix', 'Medium', 'https://leetcode.com/problems/valid-sudoku', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Bitmask / Hash Set Validation across 9x9', TRUE, 'Determine if 9 x 9 Sudoku board is valid (no duplicate digits 1-9 in any row, column, or 3x3 subgrid).', 'Pattern: Hash Sets or Bitmasks. Maintain 9 sets for rows, 9 for cols, 9 for 3x3 boxes (box index: (r // 3) * 3 + (c // 3)). If digit already present in any set, board is invalid. Time: O(1), Space: O(1).'),
  ('dsa-226', 'user-default', 'goal-dsa', 'Invert Binary Tree', 'Binary Tree', 'Easy', 'https://leetcode.com/problems/invert-binary-tree', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Recursive Left/Right Subtree Swap', TRUE, 'Invert a binary tree (mirror horizontally) and return its root.', 'Pattern: Postorder / Preorder DFS Swap. Swap left and right child pointers: root.left, root.right = invert(root.right), invert(root.left). Base case returns null. Time: O(N), Space: O(H).'),
  ('dsa-104', 'user-default', 'goal-dsa', 'Maximum Depth of Binary Tree', 'Binary Tree', 'Easy', 'https://leetcode.com/problems/maximum-depth-of-binary-tree', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Recursive DFS Maximum Depth', TRUE, 'Find maximum depth (number of nodes along longest path from root down to farthest leaf) of binary tree.', 'Pattern: Postorder Height DFS. If root is null, return 0. Depth = 1 + max(maxDepth(root.left), maxDepth(root.right)). Time: O(N), Space: O(H).'),
  ('dsa-100', 'user-default', 'goal-dsa', 'Same Tree', 'Binary Tree', 'Easy', 'https://leetcode.com/problems/same-tree', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Simultaneous Node Value & Structure Equality', TRUE, 'Check if two binary trees are structurally identical and have the same node values.', 'Pattern: Dual-Tree Preorder Traversal. If both null -> true; if one null or values differ -> false; return isSameTree(p.left, q.left) and isSameTree(p.right, q.right). Time: O(N), Space: O(H).'),
  ('dsa-101', 'user-default', 'goal-dsa', 'Symmetric Tree', 'Binary Tree', 'Easy', 'https://leetcode.com/problems/symmetric-tree', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Symmetric Mirror Tree Traversal', TRUE, 'Check whether a binary tree is a mirror of itself (symmetric around its center).', 'Pattern: Mirror Pair DFS. Helper isMirror(t1, t2): t1.val == t2.val and isMirror(t1.left, t2.right) and isMirror(t1.right, t2.left). Base case both null true, one null false. Time: O(N), Space: O(H).'),
  ('dsa-572', 'user-default', 'goal-dsa', 'Subtree of Another Tree', 'Binary Tree', 'Easy', 'https://leetcode.com/problems/subtree-of-another-tree', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Subtree Tree Equality DFS Matching', TRUE, 'Determine if binary tree root contains a subtree with same structure and values as subRoot.', 'Pattern: DFS + Tree Equality Helper. At each node in root, check if isSameTree(root, subRoot). If not, recursively check isSubtree(root.left, subRoot) or isSubtree(root.right, subRoot). Time: O(N * M), Space: O(H).'),
  ('dsa-543', 'user-default', 'goal-dsa', 'Diameter of Binary Tree', 'Binary Tree', 'Easy', 'https://leetcode.com/problems/diameter-of-binary-tree', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Postorder Subtree Heights Path Maximization', TRUE, 'Compute diameter (length of longest path between any two nodes) of binary tree.', 'Pattern: Bottom-Up Postorder DFS. At each node, compute height of left and right subtrees. Update global_diameter = max(global_diameter, left_h + right_h). Return 1 + max(left_h, right_h). Time: O(N), Space: O(H).'),
  ('dsa-110', 'user-default', 'goal-dsa', 'Balanced Binary Tree', 'Binary Tree', 'Easy', 'https://leetcode.com/problems/balanced-binary-tree', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Bottom-Up Height Checking (-1 Sentinel)', TRUE, 'Determine if binary tree is height-balanced (depth of two subtrees of every node never differs by > 1).', 'Pattern: Early-Exit Postorder DFS. Return height if balanced; return -1 sentinel immediately if left or right subtree is unbalanced or |left_h - right_h| > 1. Avoids O(N^2) top-down checks. Time: O(N), Space: O(H).'),
  ('dsa-113', 'user-default', 'goal-dsa', 'Path Sum II', 'Binary Tree', 'Medium', 'https://leetcode.com/problems/path-sum-ii', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Root-to-Leaf Backtracking Path Sum', FALSE, 'Find all root-to-leaf paths where sum of node values equals targetSum.', 'Pattern: DFS Path Backtracking. Maintain current_path list and remaining sum. At leaf node, if remaining == leaf.val, add copy of current_path to result. Pop node from path on backtrack. Time: O(N), Space: O(H).'),
  ('dsa-102', 'user-default', 'goal-dsa', 'Binary Tree Level Order Traversal', 'Binary Tree', 'Medium', 'https://leetcode.com/problems/binary-tree-level-order-traversal', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Queue-Based FIFO Level Order Traversal', TRUE, 'Return level order traversal of binary tree''s node values (level by level, left to right).', 'Pattern: BFS Queue by Level. Initialize queue with root. For each level, record queue length L; pop L nodes and append to level list; enqueue non-null children. Time: O(N), Space: O(W) where W is max tree width.'),
  ('dsa-199', 'user-default', 'goal-dsa', 'Binary Tree Right Side View', 'Binary Tree', 'Medium', 'https://leetcode.com/problems/binary-tree-right-side-view', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Level Order Last Element / Rightmost DFS', TRUE, 'Return values of nodes visible from right side of binary tree ordered from top to bottom.', 'Pattern: Level Order BFS (Take Last Element) or DFS visiting right subtree before left. In DFS, add node value if current depth equals result list length. Time: O(N), Space: O(H).'),
  ('dsa-236', 'user-default', 'goal-dsa', 'Lowest Common Ancestor of a Binary Tree', 'Binary Tree', 'Medium', 'https://leetcode.com/problems/lowest-common-ancestor-of-a-binary-tree', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Postorder LCA Subtree Result Propagation', TRUE, 'Find lowest common ancestor (LCA) of two given nodes p and q in binary tree.', 'Pattern: Postorder LCA DFS. If root is null, p, or q, return root. Recurse left and right. If both return non-null, root is LCA; if only one returns non-null, propagate that non-null node upward. Time: O(N), Space: O(H).'),
  ('dsa-105', 'user-default', 'goal-dsa', 'Construct Binary Tree from Preorder and Inorder Traversal', 'Binary Tree', 'Medium', 'https://leetcode.com/problems/construct-binary-tree-from-preorder-and-inorder-traversal', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Preorder Root + Inorder Hash Partitioning', TRUE, 'Construct binary tree from preorder and inorder traversal arrays.', 'Pattern: Divide & Conquer Tree Construction. First element of preorder is root. Find root index in inorder using hash map. Elements to left in inorder form left subtree; elements to right form right subtree. Time: O(N), Space: O(N).'),
  ('dsa-103', 'user-default', 'goal-dsa', 'Binary Tree Zigzag Level Order Traversal', 'Binary Tree', 'Medium', 'https://leetcode.com/problems/binary-tree-zigzag-level-order-traversal', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Alternating Direction Level Queue Deque', FALSE, 'Return zigzag level order traversal (left to right, then right to left, alternating).', 'Pattern: Level Order BFS with Direction Flag. Run standard level order BFS with queue. If current level index is odd, reverse level list (or append to deque front) before adding to result. Time: O(N), Space: O(W).'),
  ('dsa-662', 'user-default', 'goal-dsa', 'Maximum Width of Binary Tree', 'Binary Tree', 'Medium', 'https://leetcode.com/problems/maximum-width-of-binary-tree', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'BFS Level Width with Coordinate Indexing', FALSE, 'Find maximum width (max distance between leftmost and rightmost non-null nodes) of binary tree.', 'Pattern: Level Order BFS with Binary Heap Indexing. Root index = 0; left child = 2*i + 1, right child = 2*i + 2. Normalize indices per level by subtracting first node''s index. Width = last_index - first_index + 1. Time: O(N), Space: O(W).'),
  ('dsa-437', 'user-default', 'goal-dsa', 'Path Sum III', 'Binary Tree', 'Medium', 'https://leetcode.com/problems/path-sum-iii', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Prefix Sum Hash Map on Tree Ancestor Paths', FALSE, 'Find number of paths that sum to targetSum in binary tree (path does not need to start at root or end at leaf).', 'Pattern: Prefix Sum Hash Map on DFS Call Stack. Maintain running prefix sum and map of seen prefix sums along current ancestor branch. At each node, count += map[curr_sum - target]. Decrement map count on backtrack. Time: O(N), Space: O(H).'),
  ('dsa-124', 'user-default', 'goal-dsa', 'Binary Tree Maximum Path Sum', 'Binary Tree', 'Hard', 'https://leetcode.com/problems/binary-tree-maximum-path-sum', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Postorder Subtree Gain & Global Max Path', TRUE, 'Find maximum path sum of any non-empty path in binary tree (any node to any node).', 'Pattern: Postorder Gain Maximization. Helper returns max gain node can contribute to parent: node.val + max(0, max(left_gain, right_gain)). Update global max_sum with node.val + max(0, left_gain) + max(0, right_gain). Time: O(N), Space: O(H).'),
  ('dsa-297', 'user-default', 'goal-dsa', 'Serialize and Deserialize Binary Tree', 'Binary Tree', 'Hard', 'https://leetcode.com/problems/serialize-and-deserialize-binary-tree', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Preorder DFS with Null Sentinels Serialization', TRUE, 'Design algorithm to serialize binary tree to string and deserialize string back to binary tree.', 'Pattern: Preorder DFS with Delimiters. Serialize: preorder DFS emitting val and ''N'' for null, comma-separated. Deserialize: split string into token queue/iterator; recursively reconstruct node popping front token. Time: O(N), Space: O(N).'),
  ('dsa-235', 'user-default', 'goal-dsa', 'Lowest Common Ancestor of a Binary Search Tree', 'Binary Search Tree', 'Easy', 'https://leetcode.com/problems/lowest-common-ancestor-of-a-binary-search-tree', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'BST Split Point Navigation', TRUE, 'Find lowest common ancestor (LCA) of two given nodes in a Binary Search Tree (BST).', 'Pattern: BST Invariant Navigation. If both p and q values are strictly less than root.val, LCA is in left subtree; if both strictly greater, in right subtree. First node where paths diverge is the LCA. Time: O(H), Space: O(1) iterative.'),
  ('dsa-108', 'user-default', 'goal-dsa', 'Convert Sorted Array to Binary Search Tree', 'Binary Search Tree', 'Easy', 'https://leetcode.com/problems/convert-sorted-array-to-binary-search-tree', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Divide & Conquer Midpoint Rooting', TRUE, 'Convert sorted integer array into height-balanced binary search tree.', 'Pattern: Midpoint Binary Search Tree Construction. Choose midpoint of array as root to guarantee balanced heights; recurse on left half for root.left, right half for root.right. Time: O(N), Space: O(log N) stack.'),
  ('dsa-98', 'user-default', 'goal-dsa', 'Validate Binary Search Tree', 'Binary Search Tree', 'Medium', 'https://leetcode.com/problems/validate-binary-search-tree', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Valid Range Interval Propagation [min, max]', TRUE, 'Determine if a binary tree is a valid Binary Search Tree (BST).', 'Pattern: Valid Interval Propagation. Pass allowed range (low, high) recursively. Check that low < node.val < high. For left child, update high = node.val; for right child, update low = node.val. Initial range (-inf, +inf). Time: O(N), Space: O(H).'),
  ('dsa-230', 'user-default', 'goal-dsa', 'Kth Smallest Element in a BST', 'Binary Search Tree', 'Medium', 'https://leetcode.com/problems/kth-smallest-element-in-a-bst', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Inorder Traversal Counter (Kth Element)', TRUE, 'Find kth smallest element in a binary search tree (1-indexed).', 'Pattern: Inorder Traversal (Sorted BST Invariant). Inorder traversal of BST visits nodes in strictly ascending order. Traverse iteratively with stack; decrement k on each popped node; when k reaches 0, return popped value. Time: O(H + k), Space: O(H).'),
  ('dsa-285', 'user-default', 'goal-dsa', 'Inorder Successor in BST', 'Binary Search Tree', 'Medium', 'https://leetcode.com/problems/inorder-successor-in-bst', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'BST Successor Traversal with Value Comp', TRUE, 'Find in-order successor of given node p in BST (node with smallest key greater than p.val).', 'Pattern: BST Successor Search. Start at root. If p.val >= root.val, successor must be in right subtree. If p.val < root.val, root is potential successor; record candidate and explore left subtree for closer successor. Time: O(H), Space: O(1).'),
  ('dsa-1014', 'user-default', 'goal-dsa', 'K Closest Points to Origin', 'Heap / Priority Queue', 'Medium', 'https://leetcode.com/problems/k-closest-points-to-origin', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Max-Heap of Top K Distances / Quickselect', TRUE, 'Find k closest points to origin (0, 0) on XY plane.', 'Pattern: Max-Heap of Size K or Quickselect. Maintain max-heap of size K storing (-distance, point). For each point, if distance < top, replace top. Heap retains k smallest distances. Time: O(N log K), Space: O(K).'),
  ('dsa-692', 'user-default', 'goal-dsa', 'Top K Frequent Words', 'Heap / Priority Queue', 'Medium', 'https://leetcode.com/problems/top-k-frequent-words', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Min-Heap with Custom Pair Ordering', TRUE, 'Find k most frequent words in list; return words sorted by frequency descending, then lexicographical ascending.', 'Pattern: Min-Heap with Custom Comparison. Map word frequencies. Maintain min-heap of size K with custom comparator: (freq, ReverseOrder(word)). Heap root is smallest freq / lexicographically largest. Time: O(N log K), Space: O(N).'),
  ('dsa-215', 'user-default', 'goal-dsa', 'Kth Largest Element in an Array', 'Heap / Priority Queue', 'Medium', 'https://leetcode.com/problems/kth-largest-element-in-an-array', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Min-Heap of Size K / Quickselect', TRUE, 'Find kth largest element in an unsorted array in O(N) average time.', 'Pattern: Min-Heap of Size K or Quickselect. Maintain min-heap of size K; push elements, pop when size > K; root holds kth largest. Alternatively Quickselect with random pivot achieves O(N) average time O(1) space.'),
  ('dsa-621', 'user-default', 'goal-dsa', 'Task Scheduler', 'Heap / Priority Queue', 'Medium', 'https://leetcode.com/problems/task-scheduler', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Max-Heap Frequency Greed + Idle Cooldown', TRUE, 'Find least number of intervals to complete CPU tasks with cooldown period n between identical tasks.', 'Pattern: Greedy Frequency Counting or Max-Heap. Most frequent task dominates schedule. Max intervals bounded by (max_freq - 1) * (n + 1) + count_of_max_freq_tasks. Return max(len(tasks), formula). Time: O(N), Space: O(1).'),
  ('dsa-23', 'user-default', 'goal-dsa', 'Merge k Sorted Lists', 'Heap / Priority Queue', 'Hard', 'https://leetcode.com/problems/merge-k-sorted-lists', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'K-Way Merge with Min-Heap of Node Heads', TRUE, 'Merge k sorted linked lists and return as one sorted list.', 'Pattern: K-Way Merge with Min-Heap. Insert head node of all k lists into min-heap. Pop smallest node, append to merged list tail, and push popped_node.next into heap until empty. Time: O(N log k), Space: O(k).'),
  ('dsa-295', 'user-default', 'goal-dsa', 'Find Median from Data Stream', 'Heap / Priority Queue', 'Hard', 'https://leetcode.com/problems/find-median-from-data-stream', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Dual Min-Max Heap Balance Tracking', TRUE, 'Design data structure that supports adding numbers from data stream and finding median in O(1) time.', 'Pattern: Two Balanced Heaps. Max-heap stores smaller half; min-heap stores larger half. Balance heaps so sizes differ by at most 1. Median is top of larger heap (odd count) or average of two tops (even count). Time: O(log N) add, O(1) findMedian, Space: O(N).'),
  ('dsa-632', 'user-default', 'goal-dsa', 'Smallest Range Covering Elements from K Lists', 'Heap / Priority Queue', 'Hard', 'https://leetcode.com/problems/smallest-range-covering-elements-from-k-lists', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'K-Pointers Min-Heap Range Minimization', TRUE, 'Find smallest range [a, b] that includes at least one number from each of k sorted lists.', 'Pattern: K-Way Min-Heap with Max Tracker. Heap stores (val, list_idx, elem_idx) for one element per list. Track current_max. Range is current_max - heap_min.val. Advance pointer of minimum element to shrink range. Time: O(N log k), Space: O(k).'),
  ('dsa-208', 'user-default', 'goal-dsa', 'Implement Trie (Prefix Tree)', 'Trie', 'Medium', 'https://leetcode.com/problems/implement-trie-prefix-tree', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'TrieNode Children Hash/Array Prefix Tree', TRUE, 'Implement a trie with insert, search, and startsWith methods.', 'Pattern: Prefix Tree. Each TrieNode holds children array [26] and boolean is_end. Insert creates nodes along word characters. Search checks existence and is_end. StartsWith checks existence only. Time: O(L) per op, Space: O(Total Chars).'),
  ('dsa-211', 'user-default', 'goal-dsa', 'Design Add and Search Words Data Structure', 'Trie', 'Medium', 'https://leetcode.com/problems/design-add-and-search-words-data-structure', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Trie Traversal with Wildcard ''.'' Branching', TRUE, 'Design data structure supporting adding words and searching words with ''.'' matching any letter.', 'Pattern: Trie + DFS Wildcard Branching. Insert into standard Trie. For search, traverse nodes. When ''.'' encountered, recursively try all non-null children; for regular char, follow specific child pointer. Time: O(M) without dots, O(26^dots) worst case, Space: O(N).'),
  ('dsa-588', 'user-default', 'goal-dsa', 'Design In-Memory File System', 'Trie', 'Hard', 'https://leetcode.com/problems/design-in-memory-file-system', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Hierarchical File & Directory Path Tree', FALSE, 'Design in-memory file system supporting ls, mkdir, addContentToFile, and readContentFromFile.', 'Pattern: Trie-Like Directory Hierarchy. Node contains is_file boolean, content string, and children hash map of names to Nodes. Split path by ''/'' and traverse down children map. Time: O(Path Depth), Space: O(Filesystem Size).'),
  ('dsa-336', 'user-default', 'goal-dsa', 'Palindrome Pairs', 'Trie', 'Hard', 'https://leetcode.com/problems/palindrome-pairs', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Prefix/Suffix Trie Matching with Palindrome Check', TRUE, 'Find all pairs of distinct indices (i, j) in words list such that words[i] + words[j] is a palindrome.', 'Pattern: Reversed Words in Trie. Insert reversed words into Trie, storing word index and list of remaining palindrome suffixes. Search each word in Trie to find matching prefixes/suffixes in O(N * K^2) time.'),
  ('dsa-50', 'user-default', 'goal-dsa', 'Pow(x, n)', 'Recursion & Backtracking', 'Medium', 'https://leetcode.com/problems/powx-n', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Binary Fast Exponentiation (Divide & Conquer)', FALSE, 'Implement pow(x, n) which calculates x raised to power n in O(log N) time using recursion.', 'Pattern: Fast Exponentiation (Divide & Conquer). Master the recursive base case and subproblem halving: x^n = (x*x)^(n//2) if even, x * (x*x)^((n-1)//2) if odd. Foundational for recursive branching. Time: O(log N), Space: O(log N).'),
  ('dsa-17', 'user-default', 'goal-dsa', 'Letter Combinations of a Phone Number', 'Recursion & Backtracking', 'Medium', 'https://leetcode.com/problems/letter-combinations-of-a-phone-number', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Combinatorial Digit Mapping DFS', TRUE, 'Given string containing digits 2-9, return all possible letter combinations phone number could represent.', 'Pattern: Combinatorial DFS. Map digits to letters. At index i, loop over possible letters for digit[i], append to path, recurse for i + 1, pop character on backtrack. Time: O(4^N), Space: O(N) call stack.'),
  ('dsa-78', 'user-default', 'goal-dsa', 'Subsets', 'Recursion & Backtracking', 'Medium', 'https://leetcode.com/problems/subsets', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Include / Exclude Decision Tree Backtracking', TRUE, 'Given integer array of unique elements, return power set (all possible subsets).', 'Pattern: Binary Choice Backtracking. At each index i, branch two decisions: 1) Include nums[i] in current subset and recurse, 2) Exclude nums[i] and recurse. Total 2^N subsets. Time: O(N * 2^N), Space: O(N).'),
  ('dsa-46', 'user-default', 'goal-dsa', 'Permutations', 'Recursion & Backtracking', 'Medium', 'https://leetcode.com/problems/permutations', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Visited Array Element Permutation DFS', TRUE, 'Given array of distinct integers, return all possible permutations.', 'Pattern: Permutation Backtracking. Maintain visited boolean array. For each unused element, mark visited, add to current permutation, recurse, unmark visited on backtrack. Base case len(path) == len(nums). Time: O(N * N!), Space: O(N).'),
  ('dsa-39', 'user-default', 'goal-dsa', 'Combination Sum', 'Recursion & Backtracking', 'Medium', 'https://leetcode.com/problems/combination-sum', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Unbounded Element Pick with Target Balance', TRUE, 'Find all unique combinations of candidate numbers that sum to target, where same number may be chosen unlimited times.', 'Pattern: Unbounded Choice Backtracking. Sort candidates. At index i, include candidate[i], subtract from target, recurse on same index i (allowing reuse). If target < 0, prune. Recurse on i + 1 to explore without candidate. Time: O(2^target), Space: O(target).'),
  ('dsa-22', 'user-default', 'goal-dsa', 'Generate Parentheses', 'Recursion & Backtracking', 'Medium', 'https://leetcode.com/problems/generate-parentheses', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Open/Close Balance Constraint Backtracking', TRUE, 'Generate all combinations of well-formed parentheses given n pairs.', 'Pattern: Constrained Backtracking. Maintain open_count and close_count. Add ''('' if open_count < n; add '')'' if close_count < open_count. Terminates when string length reaches 2n. Time: O(4^N / sqrt(N)) Catalan number, Space: O(N).'),
  ('dsa-79', 'user-default', 'goal-dsa', 'Word Search', 'Recursion & Backtracking', 'Medium', 'https://leetcode.com/problems/word-search', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', '2D Grid DFS with In-Place Visited Rollback', TRUE, 'Given m x n grid of characters and string word, return true if word exists in grid moving horizontally or vertically.', 'Pattern: Grid DFS Backtracking. Start DFS from every matching first character. Check bounds and character match. Mark board[r][c] = ''#'' to mark visited; recurse 4 directions; restore board[r][c] on backtrack. Time: O(M * N * 3^L), Space: O(L).'),
  ('dsa-212', 'user-default', 'goal-dsa', 'Word Search II', 'Recursion & Backtracking', 'Hard', 'https://leetcode.com/problems/word-search-ii', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Trie-Guided Multi-Word Grid DFS Backtracking', TRUE, 'Find all words from dictionary that can be formed by characters of adjacent cells in m x n board.', 'Pattern: Trie-Pruned Grid Backtracking. Insert all words into Trie. DFS grid starting from each cell; traverse Trie simultaneously. If grid character is not in current Trie node children, prune immediately. Time: O(M * N * 4 * 3^(L-1)), Space: O(Total Trie Chars).'),
  ('dsa-37', 'user-default', 'goal-dsa', 'Sudoku Solver', 'Recursion & Backtracking', 'Hard', 'https://leetcode.com/problems/sudoku-solver', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Exact Cover 9x9 Constraint Sudoku Backtracking', TRUE, 'Solve a 9 x 9 Sudoku puzzle by filling empty cells ''.'' such that every row, column, and 3x3 subbox contains digits 1-9.', 'Pattern: Constraint Satisfaction Backtracking. Find next empty cell. Try digits ''1'' through ''9''. Check if digit is valid in row, col, box. If valid, place digit and recurse; if recursion succeeds return true; else undo placement and try next digit. Time: Exponential O(9^empty), Space: O(81).'),
  ('dsa-51', 'user-default', 'goal-dsa', 'N-Queens', 'Recursion & Backtracking', 'Hard', 'https://leetcode.com/problems/n-queens', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Diagonal, Anti-Diagonal, Column Bitmask Backtracking', TRUE, 'Place n queens on n x n chessboard such that no two queens attack each other.', 'Pattern: Row-by-Row Board Backtracking. Place queens row by row. Track attacked columns (col), main diagonals (r - c), and anti-diagonals (r + c) using sets or bitmasks. Prune invalid placements in O(1). Time: O(N!), Space: O(N).'),
  ('dsa-733', 'user-default', 'goal-dsa', 'Flood Fill', 'Graph', 'Easy', 'https://leetcode.com/problems/flood-fill', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Connected Component Grid DFS/BFS', TRUE, 'Perform flood fill on image starting from pixel (sr, sc) replacing connected pixels of same starting color with newColor.', 'Pattern: Connected Component DFS. If starting color equals newColor, return image immediately. Recurse 4 directions changing matching colored pixels to newColor. Time: O(M*N), Space: O(M*N) call stack.'),
  ('dsa-200', 'user-default', 'goal-dsa', 'Number of Islands', 'Graph', 'Medium', 'https://leetcode.com/problems/number-of-islands', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Island Grid Sink Traversal (DFS/BFS)', TRUE, 'Given m x n 2D binary grid representing map of ''1''s (land) and ''0''s (water), count number of islands.', 'Pattern: Connected Components Sink DFS. Scan grid. When ''1'' found, increment island count and trigger DFS/BFS to sink entire island by converting all connected ''1''s to ''0''s. Time: O(M*N), Space: O(M*N).'),
  ('dsa-542', 'user-default', 'goal-dsa', '01 Matrix', 'Graph', 'Medium', 'https://leetcode.com/problems/01-matrix', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Multi-Source BFS Distance Propagation', TRUE, 'Given m x n binary matrix, return distance of nearest 0 for each cell.', 'Pattern: Multi-Source BFS. Enqueue all 0-cells simultaneously with distance 0 and initialize 1-cells to infinity. BFS radiates outward layer-by-layer; first time a 1-cell is visited is guaranteed shortest distance. Time: O(M*N), Space: O(M*N).'),
  ('dsa-1036', 'user-default', 'goal-dsa', 'Rotting Oranges', 'Graph', 'Medium', 'https://leetcode.com/problems/rotting-oranges', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Multi-Source Simultaneous Minute BFS', TRUE, 'Find minimum number of minutes until no fresh orange remains in grid; rotten oranges rot adjacent 4-directional fresh oranges each minute.', 'Pattern: Multi-Source Simultaneous BFS. Enqueue all rotten oranges (2s) at minute 0 and count fresh oranges. Each BFS step rots all adjacent fresh oranges (1s) and decrements fresh count. Return minutes when fresh count reaches 0. Time: O(M*N), Space: O(M*N).'),
  ('dsa-417', 'user-default', 'goal-dsa', 'Pacific Atlantic Water Flow', 'Graph', 'Medium', 'https://leetcode.com/problems/pacific-atlantic-water-flow', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Reverse Flow Reachability BFS from Coasts', TRUE, 'Find grid coordinates where water can flow to both Pacific (top/left) and Atlantic (bottom/right) oceans.', 'Pattern: Reverse Inward BFS/DFS. Flow water backwards (from low to high elevation) starting simultaneously from Pacific borders (top/left) and Atlantic borders (bottom/right). Cells visited by both BFS traversals can reach both oceans. Time: O(M*N), Space: O(M*N).'),
  ('dsa-550', 'user-default', 'goal-dsa', 'Shortest Path to Get Food', 'Graph', 'Medium', 'https://leetcode.com/problems/shortest-path-to-get-food', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'BFS Shortest Path on Grid with Obstacles', FALSE, 'Find shortest path in grid to get food ''*'' starting from position ''*'', avoiding obstacle ''X''s.', 'Pattern: Unweighted Shortest Path BFS. Queue-based BFS starting from player start ''m''. Level-by-level traversal guarantees shortest step count when nearest food ''*'' cell is dequeued. Mark visited in-place. Time: O(M*N), Space: O(M*N).'),
  ('dsa-133', 'user-default', 'goal-dsa', 'Clone Graph', 'Graph', 'Medium', 'https://leetcode.com/problems/clone-graph', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Clone Graph with Hash Map Visited Lookup', TRUE, 'Return deep copy (clone) of connected undirected graph.', 'Pattern: DFS/BFS with Hash Map. Maintain hash map mapping original_node -> cloned_node. On visiting node, create clone and register in map; recurse on neighbors, attaching cloned neighbors to cloned node. Time: O(V + E), Space: O(V).'),
  ('dsa-261', 'user-default', 'goal-dsa', 'Graph Valid Tree', 'Graph', 'Medium', 'https://leetcode.com/problems/graph-valid-tree', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Graph Valid Tree (Cycle & Connected Component)', TRUE, 'Given n nodes and list of undirected edges, determine if edges form a valid tree.', 'Pattern: Tree Graph Invariant. An undirected graph is a valid tree iff: 1) Number of edges == n - 1, and 2) All nodes are connected (single connected component without cycles verified via DSU or BFS). Time: O(V + E), Space: O(V).'),
  ('dsa-323', 'user-default', 'goal-dsa', 'Number of Connected Components in an Undirected Graph', 'Graph', 'Medium', 'https://leetcode.com/problems/number-of-connected-components-in-an-undirected-graph', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Number of Connected Components in an Undirected Graph', TRUE, 'Given n nodes labeled 0 to n - 1 and list of undirected edges, find number of connected components in graph.', 'Pattern: Disjoint Set Union (Union-Find) or BFS/DFS. Initialize count = n. For each edge (u, v), if union(u, v) succeeds, decrement count by 1. Remaining count is number of connected components. Time: O(V + E * alpha(V)), Space: O(V).'),
  ('dsa-721', 'user-default', 'goal-dsa', 'Accounts Merge', 'Graph', 'Medium', 'https://leetcode.com/problems/accounts-merge', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Disjoint Set Union (DSU) / Connected Components', TRUE, 'Merge accounts belonging to same person given list of names and email addresses.', 'Pattern: Disjoint Set Union on Emails. Map each email to unique ID and owner name. Union the first email of each account with all subsequent emails in that account. Group emails by root parent, sort emails, and prepend owner name. Time: O(N * K log K), Space: O(N * K).'),
  ('dsa-207', 'user-default', 'goal-dsa', 'Course Schedule', 'Graph', 'Medium', 'https://leetcode.com/problems/course-schedule', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Kahn''s Algorithm (In-Degree) / Cycle DFS', TRUE, 'Determine if you can finish all courses given prerequisites [a, b] (directed edge b -> a).', 'Pattern: Topological Sort / Cycle Detection. Build adjacency list and compute in-degrees. Enqueue all courses with in-degree 0. Dequeue course, decrement in-degree of dependent courses, and enqueue if in-degree becomes 0. If processed count == numCourses, finishable. Time: O(V + E), Space: O(V + E).'),
  ('dsa-210', 'user-default', 'goal-dsa', 'Course Schedule II', 'Graph', 'Medium', 'https://leetcode.com/problems/course-schedule-ii', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Topological Sort Order Generation', TRUE, 'Return ordering of courses you should take to finish all courses; return empty array if impossible.', 'Pattern: Kahn''s Topological Order Extraction. Run Kahn''s algorithm with queue of 0-in-degree nodes. Append each dequeued node to course order list. If order length equals numCourses, return order; else cycle exists, return []. Time: O(V + E), Space: O(V + E).'),
  ('dsa-310', 'user-default', 'goal-dsa', 'Minimum Height Trees', 'Graph', 'Medium', 'https://leetcode.com/problems/minimum-height-trees', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Leaf Pruning Topological Inward BFS', TRUE, 'Find all roots of Minimum Height Trees (MHTs) in tree of n nodes.', 'Pattern: Leaf-Trimming Topological BFS. Tree centroid can have at most 1 or 2 nodes. Repeatedly remove all degree-1 leaf nodes and their edges layer-by-layer until <= 2 nodes remain in graph. Surviving nodes are MHT roots. Time: O(V), Space: O(V).'),
  ('dsa-269', 'user-default', 'goal-dsa', 'Alien Dictionary', 'Graph', 'Hard', 'https://leetcode.com/problems/alien-dictionary', 45, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Character Precedence DAG Topological Sort', TRUE, 'Given sorted dictionary of alien language words, derive lexicographical order of alien letters.', 'Pattern: DAG Topological Sort on Character Precedence. Compare adjacent words to find first differing character; add directed edge c1 -> c2. Check invalid prefix rule (e.g. ''abc'' after ''abcd''). Run Kahn''s algorithm; if order length != total unique letters, cycle exists (invalid). Time: O(Total Chars), Space: O(U + E).'),
  ('dsa-893', 'user-default', 'goal-dsa', 'All Nodes Distance K in Binary Tree', 'Graph', 'Medium', 'https://leetcode.com/problems/all-nodes-distance-k-in-binary-tree', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Tree to Graph Node Mapping + BFS', FALSE, 'Find all nodes at distance k from target node in binary tree.', 'Pattern: Annotate Parents + Graph BFS. Run DFS to populate parent pointers in hash map, transforming tree into undirected graph. Run BFS outward from target node up to k steps. Time: O(N), Space: O(N).'),
  ('dsa-1142', 'user-default', 'goal-dsa', 'Minimum Knight Moves', 'Graph', 'Medium', 'https://leetcode.com/problems/minimum-knight-moves', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Bidirectional BFS Shortest Move Path', FALSE, 'Find minimum number of steps for knight on infinite chessboard to reach target (x, y).', 'Pattern: Bidirectional BFS or Quadrant Symmetry. Exploit 8-fold symmetry: map target to first quadrant (abs(x), abs(y)). Run bidirectional BFS from origin and target, meeting in middle to reduce search space from O(8^d) to O(8^(d/2)). Time: O(Steps), Space: O(Steps).'),
  ('dsa-803', 'user-default', 'goal-dsa', 'Cheapest Flights Within K Stops', 'Graph', 'Medium', 'https://leetcode.com/problems/cheapest-flights-within-k-stops', 45, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Dijkstra Priority Queue / Bellman-Ford with K Stops', TRUE, 'Find cheapest flight price from src to dst with at most k stops.', 'Pattern: Bellman-Ford (K+1 Relaxations) or Modified Dijkstra. Bellman-Ford relaxes all flight edges k + 1 times using snapshot of previous prices to prevent using > k stops. Time: O(K * E), Space: O(V).'),
  ('dsa-127', 'user-default', 'goal-dsa', 'Word Ladder', 'Graph', 'Hard', 'https://leetcode.com/problems/word-ladder', 45, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Shortest Word Transformation Bidirectional BFS', TRUE, 'Find length of shortest transformation sequence from beginWord to endWord changing one character at a time using wordList.', 'Pattern: Bidirectional BFS. Maintain begin_set and end_set. Always expand smaller set to minimize branching factor. Generate intermediate word variations (*at -> bat, cat); return distance when search frontiers intersect. Time: O(M^2 * N), Space: O(M * N).'),
  ('dsa-329', 'user-default', 'goal-dsa', 'Longest Increasing Path in a Matrix', 'Graph', 'Hard', 'https://leetcode.com/problems/longest-increasing-path-in-a-matrix', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Memoized DFS on Directed Acyclic Graph', TRUE, 'Find length of longest increasing path in m x n integer matrix.', 'Pattern: DAG Memoized DFS. Since path must be strictly increasing, graph is acyclic. At each cell, DFS 4 directions into strictly greater neighbors: dfs(r, c) = 1 + max(dfs(nr, nc)). Memoize results in dp[r][c] to evaluate each cell once. Time: O(M*N), Space: O(M*N).'),
  ('dsa-833', 'user-default', 'goal-dsa', 'Bus Routes', 'Graph', 'Hard', 'https://leetcode.com/problems/bus-routes', 45, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'BFS across Route Intersections', FALSE, 'Find least number of buses to take from source bus stop to target bus stop.', 'Pattern: Route-Level BFS. Map each stop to list of bus routes passing through it. Run BFS where graph nodes are bus routes (not individual stops) to compress graph; visited set tracks routes already boarded. Time: O(Total Stops on Routes), Space: O(Routes * Stops).'),
  ('dsa-55', 'user-default', 'goal-dsa', 'Jump Game', 'Greedy', 'Medium', 'https://leetcode.com/problems/jump-game', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Greedy Max Reachable Index', TRUE, 'Determine if you can reach last index of array given max jump length at each position.', 'Pattern: Greedy Farthest Reach. Track max_reach = 0. Iterate through array; if current index i > max_reach, return false (unreachable). Update max_reach = max(max_reach, i + nums[i]). If max_reach >= n - 1, return true. Time: O(N), Space: O(1).'),
  ('dsa-134', 'user-default', 'goal-dsa', 'Gas Station', 'Greedy', 'Medium', 'https://leetcode.com/problems/gas-station', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Greedy Running Balance / Circular Subarray', TRUE, 'Find starting gas station index to travel clockwise around circular route once; return -1 if impossible.', 'Pattern: Greedy Prefix Balance. If total_gas < total_cost, complete circuit is impossible (return -1). Maintain running_tank; whenever running_tank < 0, reset start_station = i + 1 and running_tank = 0. Time: O(N), Space: O(1).'),
  ('dsa-70', 'user-default', 'goal-dsa', 'Climbing Stairs', 'Dynamic Programming', 'Easy', 'https://leetcode.com/problems/climbing-stairs', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Fibonacci 1D State Transition (dp[i] = dp[i-1] + dp[i-2])', TRUE, 'Calculate number of distinct ways to climb to top of staircase with n steps taking 1 or 2 steps at a time.', 'Pattern: 1D Fibonacci DP. Base cases: dp[1] = 1, dp[2] = 2. Transition: dp[i] = dp[i-1] + dp[i-2]. Maintain two variables (a, b) to compute in O(N) time and O(1) space.'),
  ('dsa-53', 'user-default', 'goal-dsa', 'Maximum Subarray', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/maximum-subarray', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Kadane''s Algorithm (Extend or Restart Subarray)', TRUE, 'Find subarray with largest sum within integer array nums and return its sum.', 'Pattern: Kadane''s Algorithm. At each element, either add to running subarray sum or start fresh subarray: curr_sum = max(num, curr_sum + num); max_sum = max(max_sum, curr_sum). Time: O(N), Space: O(1).'),
  ('dsa-198', 'user-default', 'goal-dsa', 'House Robber', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/house-robber', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Alternating Robbery State (rob vs skip)', TRUE, 'Determine maximum money you can rob tonight without alerting police (cannot rob adjacent houses).', 'Pattern: State Machine DP. At house i: rob = max(rob[i-1], rob[i-2] + nums[i]). Maintain two variables prev1 and prev2 for O(1) space. Time: O(N), Space: O(1).'),
  ('dsa-152', 'user-default', 'goal-dsa', 'Maximum Product Subarray', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/maximum-product-subarray', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Dual Min/Max Tracking with Sign Inversion', TRUE, 'Find contiguous subarray within integer array that has largest product.', 'Pattern: Min/Max Running Product DP. Negative number flips min into max and max into min. Track both max_prod and min_prod at each index: if num < 0, swap max_prod and min_prod; max_prod = max(num, max_prod * num). Time: O(N), Space: O(1).'),
  ('dsa-91', 'user-default', 'goal-dsa', 'Decode Ways', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/decode-ways', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', '1D String Prefix Single/Double Digit Decoding', TRUE, 'Determine total number of ways to decode string of digits into letters (1 -> ''A'', 26 -> ''Z'').', 'Pattern: 1D Prefix DP. dp[i] adds dp[i-1] if single digit s[i-1] != ''0'' (valid 1-9); dp[i] adds dp[i-2] if two digits s[i-2:i] are between ''10'' and ''26''. Maintain two rolling variables. Time: O(N), Space: O(1).'),
  ('dsa-139', 'user-default', 'goal-dsa', 'Word Break', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/word-break', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', '1D Substring Segmentation Boolean DP', TRUE, 'Determine if string can be segmented into space-separated sequence of dictionary words.', 'Pattern: 1D Boolean Dynamic Programming. dp[i] is true if s[0:i] can be segmented into words. For each i in 1..n, loop j in 0..i: if dp[j] and s[j:i] in wordSet, dp[i] = true; break. Time: O(N^2), Space: O(N).'),
  ('dsa-62', 'user-default', 'goal-dsa', 'Unique Paths', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/unique-paths', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', '2D Grid Path Accumulation (dp[r][c] = top + left)', TRUE, 'Find number of possible unique paths for robot to reach bottom-right corner of m x n grid moving only right or down.', 'Pattern: 2D Grid DP. dp[r][c] = dp[r-1][c] + dp[r][c-1]. Optimize to 1D row array: row[c] += row[c-1]. Alternatively compute via combinatorics: (m+n-2) choose (m-1). Time: O(M*N), Space: O(N).'),
  ('dsa-221', 'user-default', 'goal-dsa', 'Maximal Square', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/maximal-square', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', '2D Min(Top, Left, Top-Left) + 1 Square Expansion', TRUE, 'Find largest square containing only 1''s in binary matrix and return its area.', 'Pattern: 2D Minimum Square DP. If matrix[r][c] == ''1'', dp[r][c] = 1 + min(dp[r-1][c], dp[r][c-1], dp[r-1][c-1]). Track maximum side length seen. Area = max_side * max_side. Time: O(M*N), Space: O(N) optimized.'),
  ('dsa-322', 'user-default', 'goal-dsa', 'Coin Change', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/coin-change', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Unbounded Knapsack Coin Minimization', TRUE, 'Find fewest number of coins needed to make up amount; return -1 if impossible.', 'Pattern: Unbounded Knapsack DP. Initialize dp array of size amount + 1 with infinity; dp[0] = 0. For each coin, for a in range(coin, amount + 1): dp[a] = min(dp[a], dp[a - coin] + 1). Time: O(amount * len(coins)), Space: O(amount).'),
  ('dsa-416', 'user-default', 'goal-dsa', 'Partition Equal Subset Sum', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/partition-equal-subset-sum', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', '0/1 Knapsack Target Half-Sum Partition', TRUE, 'Determine if array can be partitioned into two subsets with equal sum.', 'Pattern: 0/1 Knapsack Partition DP. If total_sum is odd, return false; target = total_sum // 2. Boolean DP array dp[s] represents whether sum s is achievable. Iterate backwards to prevent element reuse: dp[s] |= dp[s - num]. Time: O(N * target), Space: O(target).'),
  ('dsa-377', 'user-default', 'goal-dsa', 'Combination Sum IV', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/combination-sum-iv', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Permutation Sum Counting (Unbounded Order-Sensitive)', FALSE, 'Find number of possible combinations that add up to target positive integer where different sequences are counted as different.', 'Pattern: Permutation DP. Target loop is outer, numbers loop is inner: for t in 1..target: for num in nums: dp[t] += dp[t - num] if t >= num. dp[0] = 1. Time: O(target * len(nums)), Space: O(target).'),
  ('dsa-300', 'user-default', 'goal-dsa', 'Longest Increasing Subsequence', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/longest-increasing-subsequence', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'LIS Patience Sorting / Binary Search O(N log N)', TRUE, 'Find length of longest strictly increasing subsequence in integer array.', 'Pattern: Patience Sorting / Binary Search. Maintain tails array where tails[i] stores smallest tail of all increasing subsequences of length i + 1. Binary search insertion point: if num > all tails append, else replace tails[idx] = num. Length of tails is LIS. Time: O(N log N), Space: O(N).'),
  ('dsa-1352', 'user-default', 'goal-dsa', 'Maximum Profit in Job Scheduling', 'Dynamic Programming', 'Hard', 'https://leetcode.com/problems/maximum-profit-in-job-scheduling', 45, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Weighted Interval Scheduling DP with Binary Search', TRUE, 'Find maximum profit in scheduling non-overlapping jobs, each with start, end, and profit.', 'Pattern: Weighted Job Scheduling DP + Binary Search. Sort jobs by end time. dp[i] = max(dp[i-1], job.profit + dp[latest_non_overlapping_job]). Binary search finds latest job ending <= job.start in O(log N). Time: O(N log N), Space: O(N).'),
  ('dsa-136', 'user-default', 'goal-dsa', 'Single Number', 'Bit Manipulation & Math', 'Easy', 'https://leetcode.com/problems/single-number', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Bitwise XOR Cancellation (a ^ a = 0)', TRUE, 'Find single element that appears only once in array where every other element appears twice in O(1) space.', 'Pattern: Bitwise XOR Cancellation. XORing a number with itself yields 0 (a ^ a = 0), and XOR with 0 yields the number (a ^ 0 = a). XOR all numbers together; all duplicates cancel out, leaving single number. Time: O(N), Space: O(1).'),
  ('dsa-268', 'user-default', 'goal-dsa', 'Missing Number', 'Bit Manipulation & Math', 'Easy', 'https://leetcode.com/problems/missing-number', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Gauss Formula Sum Difference / XOR', TRUE, 'Find only number in range [0, n] missing from array containing n distinct numbers.', 'Pattern: Gauss Sum or XOR. Expected sum is n * (n + 1) // 2. Missing number = expected_sum - sum(nums). Alternatively XOR all numbers in [0, n] with all numbers in array. Time: O(N), Space: O(1).'),
  ('dsa-191', 'user-default', 'goal-dsa', 'Number of 1 Bits', 'Bit Manipulation & Math', 'Easy', 'https://leetcode.com/problems/number-of-1-bits', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Brian Kernighan''s Bit Trick (n & (n - 1))', TRUE, 'Write function that takes positive integer and returns number of set bits (''1''s) in binary representation (Hamming weight).', 'Pattern: Brian Kernighan''s Algorithm. Operation n & (n - 1) flips the lowest set bit to 0. Loop while n > 0, incrementing count. Loop runs exactly as many times as there are set bits. Time: O(Set Bits), Space: O(1).'),
  ('dsa-338', 'user-default', 'goal-dsa', 'Counting Bits', 'Bit Manipulation & Math', 'Easy', 'https://leetcode.com/problems/counting-bits', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'DP Transition from Right-Shifted Counter', TRUE, 'Given integer n, return array of length n + 1 where ans[i] is number of 1''s in binary representation of i in O(N) time.', 'Pattern: Bit Counting DP. Number of set bits in i equals bits in right-shifted number plus lowest bit: dp[i] = dp[i >> 1] + (i & 1). Compute in single linear pass. Time: O(N), Space: O(1) auxiliary.'),
  ('dsa-190', 'user-default', 'goal-dsa', 'Reverse Bits', 'Bit Manipulation & Math', 'Easy', 'https://leetcode.com/problems/reverse-bits', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Bit Shifting & Masking Inversion', TRUE, 'Reverse bits of given 32 bits unsigned integer.', 'Pattern: Bit Shifting & Masking. Loop 32 times: shift result left by 1 and bitwise OR with lowest bit of n (n & 1); shift n right by 1. Time: O(1) [32 ops], Space: O(1).'),
  ('dsa-67', 'user-default', 'goal-dsa', 'Add Binary', 'Bit Manipulation & Math', 'Easy', 'https://leetcode.com/problems/add-binary', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Bit-by-Bit Binary Addition with Carry', FALSE, 'Given two binary strings a and b, return their sum as binary string.', 'Pattern: Binary String Carry Addition. Pointers at end of strings. In loop: total = carry + (a[i] == ''1'') + (b[j] == ''1''); append total % 2; carry = total // 2. Reverse result string at end. Time: O(max(N, M)), Space: O(1).'),
  ('dsa-9', 'user-default', 'goal-dsa', 'Palindrome Number', 'Bit Manipulation & Math', 'Easy', 'https://leetcode.com/problems/palindrome-number', 15, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Half-Reversal Numeric Modulo Palindrome', FALSE, 'Determine whether integer is palindrome without converting integer to string.', 'Pattern: Half-Integer Reversal. Negative numbers and numbers ending in 0 (except 0) are never palindromes. Reverse second half: rev = rev * 10 + x % 10, x //= 10 until x <= rev. Palindrome if x == rev or x == rev // 10. Time: O(log10(N)), Space: O(1).'),
  ('dsa-13', 'user-default', 'goal-dsa', 'Roman to Integer', 'Bit Manipulation & Math', 'Easy', 'https://leetcode.com/problems/roman-to-integer', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', 'Subtraction Rule Roman Numeral Accumulator', FALSE, 'Convert Roman numeral string to integer.', 'Pattern: Subtraction Rule Accumulation. Map Roman chars to values. If current value is less than next value, subtract current value (e.g. IV = 5 - 1 = 4); otherwise add current value. Time: O(N), Space: O(1).'),
  ('dsa-7', 'user-default', 'goal-dsa', 'Reverse Integer', 'Bit Manipulation & Math', 'Medium', 'https://leetcode.com/problems/reverse-integer', 25, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', '32-Bit Integer Modulo Reverse with Overflow Guard', FALSE, 'Given signed 32-bit integer x, return x with digits reversed; return 0 if reversed overflows [-2^31, 2^31 - 1].', 'Pattern: Numeric Reverse with Overflow Check. Extract digits with x % 10. Before rev = rev * 10 + digit, verify rev does not exceed (INT_MAX - digit) // 10. Time: O(log10(N)), Space: O(1).'),
  ('mla-1-1-1', 'user-default', 'goal-aws', 'Skill 1.1.1: Extract data from data sources (for example, Amazon S3, Amazon EBS, Amazon EFS, Amazon RDS, Amazon DynamoDB, Amazon OpenSearch Service).', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', TRUE, 'Skill 1.1.1 focuses on: ''Extract data from data sources (for example, Amazon S3, Amazon EBS, Amazon EFS, Amazon RDS, Amazon DynamoDB, Amazon OpenSearch Service).''. In modern enterprise machine learnin...', 'Exam Tip: Use FSx for Lustre (linked to S3) for GPU training data caching; use S3 + Lake Formation for centralized data lake governance. Gotcha: Choosing EFS over FSx for Lustre for distributed multi-GPU training. EFS lacks the sub-millisecond Lustre parallel POSIX throughput needed to feed GPUs at 100Gbps.'),
  ('mla-1-1-2', 'user-default', 'goal-aws', 'Skill 1.1.2: Make storage decisions and conﬁgure storage services based on cost, performance, data structure, and data compliance.', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', TRUE, 'Skill 1.1.2 focuses on: ''Make storage decisions and conﬁgure storage services based on cost, performance, data structure, and data compliance.''. In modern enterprise machine learning and generative AI...', 'Exam Tip: Use FSx for Lustre (linked to S3) for GPU training data caching; use S3 + Lake Formation for centralized data lake governance. Gotcha: Choosing EFS over FSx for Lustre for distributed multi-GPU training. EFS lacks the sub-millisecond Lustre parallel POSIX throughput needed to feed GPUs at 100Gbps.'),
  ('mla-1-1-3', 'user-default', 'goal-aws', 'Skill 1.1.3: Troubleshoot and debug data ingestion and storage issues that involve capacity and scalability.', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', FALSE, 'Skill 1.1.3 focuses on: ''Troubleshoot and debug data ingestion and storage issues that involve capacity and scalability.''. In modern enterprise machine learning and generative AI architectures, this t...', 'Exam Tip: Use FSx for Lustre (linked to S3) for GPU training data caching; use S3 + Lake Formation for centralized data lake governance. Gotcha: Choosing EFS over FSx for Lustre for distributed multi-GPU training. EFS lacks the sub-millisecond Lustre parallel POSIX throughput needed to feed GPUs at 100Gbps.'),
